    frame: 0,
    timeMs: 0,
    left: leftStick.snapshot(),
    right: rightStick.snapshot(),
    intent: {
      moveX: 0,
      moveY: 0,
      aimX: 0,
      aimY: 0,
      fire: false,
      sourceMove: 'none',
      sourceAim: 'none',
    },
  };

