  let spellSlot = null;   // direct slot pick (0, 1, …) or null
  let spellCycle = 0;     // +1 forward, -1 back, 0 none

  on(window, 'keydown', (e) => {
    const k = e.key.toLowerCase();
    if (k === '1') spellSlot = 0;
